PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE ProfilUser (
  id_user INTEGER PRIMARY KEY AUTOINCREMENT,
  full_name TEXT,
  role INTEGER,
  age INTEGER,
  gender TEXT,
  height INTEGER,
  weight INTEGER,
  activity TEXT,
  calory INTEGER,
  protein INTEGER,
  carb INTEGER,
  fat INTEGER,
  diet_goal TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
, password TEXT, email TEXT);
CREATE TABLE Makanan (
  code TEXT PRIMARY KEY,
  food_name TEXT,
  water REAL,
  cal REAL,
  protein REAL,
  fat REAL,
  carb REAL,
  fiber REAL
);
CREATE TABLE LogHarian (
  id_log INTEGER PRIMARY KEY AUTOINCREMENT,
  id_user INTEGER NOT NULL,
  kode_makanan TEXT NOT NULL,
  meal_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  portion REAL,
  cal REAL,
  protein REAL,
  carb REAL,
  fat REAL,
  category TEXT,
  FOREIGN KEY (id_user) REFERENCES ProfilUser(id_user) ON DELETE CASCADE,
  FOREIGN KEY (kode_makanan) REFERENCES makanan(code)
);
CREATE TABLE CacheResep (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            nama_makanan TEXT UNIQUE,
            data_json_bahan TEXT
        , cal REAL, protein REAL, carb REAL, fat REAL, status INTEGER, water REAL, fiber REAL);
CREATE TABLE request_makanan (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            nama_makanan TEXT UNIQUE,
            waktu_input TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        );
DELETE FROM sqlite_sequence;
COMMIT;
